/// <summary>
/// PA 13.01.22
/// </summary>
/// <param name = "_prodId">ProdId</param>
/// <returns>ProdId</returns>
private ProdId parmProdId(ProdId _prodId = ProdId)
{
    prodId = _prodId;
    return prodId;
}

/// <summary>
/// PA 13.01.22
/// </summary>
/// <returns>BusinessEventsContract</returns>
[Wrappable(true), Replaceable(true)]
protected BusinessEventsContract buildContract()
{
    return new NDXProdStatusChangedGenerateTransportLabelEventContractInteraction().newFromProdId(prodId);
}

/// <summary>
/// PA 13.01.22
/// Constructor
/// </summary>
/// <param name = "_prodId">ProdId</param>
/// <returns>NDXProdStatusChangedGenerateTransportLabelEvent</returns>
static public NDXProdStatusChangedGenerateTransportLabelEvent newFromProdId(ProdId _prodId)
{
    NDXProdStatusChangedGenerateTransportLabelEvent businessEvent = new NDXProdStatusChangedGenerateTransportLabelEvent();
    businessEvent.parmProdId(_prodId);
    return businessEvent;
}
